sp_widget.client_script:
function($scope, $rootScope, $timeout) {
  var dadosOriginais = $scope.data.chartBarData || [];

  var grafico = null;

  // Variável para controlar exibição
  $scope.temDados = dadosOriginais.length > 0;

  function montarGrafico(dados) {
    if (!dados || dados.length === 0) {
      if (grafico) {
        grafico.destroy();
        grafico = null;
      }
      $scope.temDados = false;
      $scope.$applyAsync();
      return;
    }

    $scope.temDados = true;
    $scope.$applyAsync();

    var anos = dados.map(function(d) { return d.ano; });
    var despesaLiquidaPessoal = dados.map(function(d) { return d.ativo; });
    var receitaCorrenteRCL = dados.map(function(d) { return d.inativo; });
    var comprometimentos = dados.map(function(d) { return d.comprometimento || 0; });
    var linhaFixa = [];
    for (var i = 0; i < anos.length; i++) {
      linhaFixa.push(54);
    }

    var ctx = document.getElementById('graficoBarra').getContext('2d');

    if (grafico) {
      grafico.destroy();
    }

    grafico = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: anos,
        datasets: [
          {
            label: 'Despesa Líquida com o pessoal',
            data: despesaLiquidaPessoal,
            backgroundColor: '#6BB7F0',
            yAxisID: 'yLeft'
          },
          {
            label: 'Receita Corrente Líquida - RCL - para fins de % pessoal',
            data: receitaCorrenteRCL,
            backgroundColor: '#4A75B1',
            yAxisID: 'yLeft'
          },
          {
            label: 'Comprometimento (%)',
            type: 'line',
            borderColor: '#003f87',
            borderWidth: 2,
            fill: false,
            data: comprometimentos,
            yAxisID: 'yRight'
          },
          {
            label: 'Limite (54%)',
            type: 'line',
            borderColor: '#D90C0C',
            borderDash: [5, 5],
            borderWidth: 2,
            fill: false,
            data: linhaFixa,
            yAxisID: 'yRight'
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: {
            title: { display: true, text: 'Ano' },
            stacked: false
          },
          yLeft: {
            position: 'left',
            beginAtZero: true,
            ticks: {
              stepSize: 5,
              callback: function(value) {
                return value.toLocaleString('pt-BR') + '';
              }
            },
            title: { display: true, text: 'Milhões (R$)' }
          },
          yRight: {
            position: 'right',
            beginAtZero: true,
            max: 70,
            ticks: {
              stepSize: 10,
              callback: function(value) {
                return value + '%';
              }
            },
            title: { display: true, text: 'Comprometimento (%)' },
            grid: { drawOnChartArea: false }
          }
        },
        plugins: {
          tooltip: {
            callbacks: {
              label: function(context) {
                if (context.dataset.yAxisID === 'yRight') {
                  return context.dataset.label + ': ' + context.parsed.y + '%';
                }
                return context.dataset.label + ': ' + context.parsed.y.toLocaleString('pt-BR') + '';
              }
            }
          },
          legend: { position: 'top' }
        }
      }
    });
  }

  function filtrarDadosPorAno(ano) {
    if (!ano) {
      return dadosOriginais;
    }
    return dadosOriginais.filter(function(d) {
      return d.ano == ano;
    });
  }

  $rootScope.$on('anoSelecionado', function(event, ano) {
    var dadosFiltrados = filtrarDadosPorAno(ano);
    montarGrafico(dadosFiltrados);
  });

  $timeout(function() {
    montarGrafico(dadosOriginais);
  }, 300);
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div {
 font-family: 'Roboto Flex', sans-serif;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}
@media (min-width: 2001px) {
    .chart-wrapper {
        height: 72rem;
    }
}

@media (min-width: 1884px) and (max-width: 2000px) {
    .chart-wrapper {
        height: 78rem;
    }
}

@media (min-width: 1511px) and (max-width: 1883px) {
    .chart-wrapper {
        height: 76.5rem;
    }
}

@media (min-width: 990px) and (max-width: 1510px) {
    .chart-wrapper {
        height: 84.5rem;
    }
}

sp_widget.script:
(function() {
  var gr = new GlideRecord('x_sded9_portal_t_0_u_despesa_pessoal');
  gr.addQuery('u_ano', '>=', 2019);
  gr.addQuery('u_ano', '<=', 2024);
  gr.orderBy('u_ano');
  gr.query();

  var dados = [];
  while (gr.next()) {
    dados.push({
      ano: gr.getValue('u_ano'),
      ativo: parseFloat(gr.getValue('u_despesa_liquida_pedidos')) / 1,
      inativo: parseFloat(gr.getValue('u_receita_corrente_liquida')) / 1,
      comprometimento: parseFloat(gr.getValue('u_comprometimento_rcl')) || 0
    });
  }

  data.chartBarData = dados;
})();
